        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(3, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(3),
            caps: &caps,
        };

        register_port_for(&ipc, 1, 3, sink);
        enqueue(&ipc, 1, &[1, 2, 3, 4], sink);
