    /// `pipe_create` mints a read/write descriptor pair in the caller's own
    /// open table and the pair round-trips bytes through `fs_write` /
    /// `fs_read`; a drained pipe whose write end closed is end-of-stream,
    /// and a write with no reader fails closed with `BrokenPipe`
    /// (`plans/SPAWN.md` SP10).
    #[test]
    fn pipe_create_mints_a_pair_that_round_trips_bytes() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) =
            send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, b"ping");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        // Unprivileged: pipes and pipe I/O need no capability at all.
        let caps = make_caps_record(2, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // The two new descriptors land at 0x1800 (read end first).
        assert_eq!(h.pipe_create(&ctx, 0x1800), Ok(0));
        let mut fds = [0u8; 8];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1800), &mut fds).expect("readable");
        })
        .expect("caller has a space");
        let read_fd = u32::from_ne_bytes([fds[0], fds[1], fds[2], fds[3]]);
        let write_fd = u32::from_ne_bytes([fds[4], fds[5], fds[6], fds[7]]);
        assert_eq!((read_fd, write_fd), (4, 5));

        // Bytes flow write end -> read end; the offset is ignored.
        assert_eq!(h.fs_write(&ctx, write_fd, 999, 0x1000, 4), Ok(4));
        assert_eq!(h.fs_read(&ctx, read_fd, 999, 0x1100, 4), Ok(4));
        let mut out = [0u8; 4];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1100), &mut out).expect("readable");
        })
        .expect("caller has a space");
        assert_eq!(&out, b"ping");

        // Close the write end: the drained pipe is end-of-stream, not a
        // park or an error.
        assert_eq!(h.fs_close(&ctx, write_fd), Ok(0));
        assert_eq!(h.fs_read(&ctx, read_fd, 0, 0x1100, 4), Ok(0));

        // A second pipe whose read end closes breaks its writer.
        assert_eq!(h.pipe_create(&ctx, 0x1800), Ok(0));
        let mut fds = [0u8; 8];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1800), &mut fds).expect("readable");
        })
        .expect("caller has a space");
        let read_fd2 = u32::from_ne_bytes([fds[0], fds[1], fds[2], fds[3]]);
        let write_fd2 = u32::from_ne_bytes([fds[4], fds[5], fds[6], fds[7]]);
        assert_eq!(h.fs_close(&ctx, read_fd2), Ok(0));
        assert_eq!(
            h.fs_write(&ctx, write_fd2, 0, 0x1000, 4),
            Err(Errno::BrokenPipe)
        );
    }

    /// `pty_create` mints a master/slave descriptor pair in the caller's own
    /// open table; input flows master → slave, cooked program output flows
    /// slave → master with `ONLCR`, the slave is a *tty* for
    /// `terminal_size`/`stream_input_mode`, and closing the slave makes a
    /// master read end-of-stream and a master write break (`plans/PTY.md`).
    #[test]
    fn pty_create_mints_a_tty_pair_that_cooks_and_round_trips() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) =
            send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, b"ping");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        // Unprivileged: a pty and its I/O need no capability at all.
        let caps = make_caps_record(2, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // A zero dimension fails closed before any descriptor is minted.
        assert_eq!(h.pty_create(&ctx, 0x1800, 0, 80), Err(Errno::OutOfRange));

        // The two new descriptors land at 0x1800 (master end first).
        assert_eq!(h.pty_create(&ctx, 0x1800, 24, 80), Ok(0));
        let mut fds = [0u8; 8];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1800), &mut fds).expect("readable");
        })
        .expect("caller has a space");
        let master_fd = u32::from_ne_bytes([fds[0], fds[1], fds[2], fds[3]]);
        let slave_fd = u32::from_ne_bytes([fds[4], fds[5], fds[6], fds[7]]);
        assert_eq!((master_fd, slave_fd), (4, 5));

        // The slave is a tty: its geometry is what the master set at create.
        assert_eq!(h.terminal_size(&ctx, slave_fd, 0x1900, 4), Ok(4));
        let mut size = [0u8; 4];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1900), &mut size).expect("readable");
        })
        .expect("caller has a space");
        assert_eq!(
            TerminalSize::from_bytes(&size),
            Ok(TerminalSize::new(24, 80).unwrap())
        );

        // Put the slave in raw mode (routed to the pty) so master input
        // flows straight through without echo, then round-trip a keystroke.
        assert_eq!(
            h.stream_input_mode(&ctx, slave_fd, InputMode::Raw.as_u32()),
            Ok(0)
        );
        assert_eq!(h.fs_write(&ctx, master_fd, 0, 0x1000, 4), Ok(4));
        assert_eq!(h.fs_read(&ctx, slave_fd, 0, 0x1100, 4), Ok(4));
        let mut out = [0u8; 4];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1100), &mut out).expect("readable");
        })
        .expect("caller has a space");
        assert_eq!(&out, b"ping");

        // Stage a bare-LF program line and prove the slave write cooks it to
        // CR LF (ONLCR) on the master's read side.
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_out(space, physmap, VirtAddr::new(0x1200), b"a\nb").expect("writable");
        })
        .expect("caller has a space");
        assert_eq!(h.fs_write(&ctx, slave_fd, 0, 0x1200, 3), Ok(3));
        assert_eq!(h.fs_read(&ctx, master_fd, 0, 0x1100, 8), Ok(4));
        let mut cooked = [0u8; 4];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1100), &mut cooked).expect("readable");
        })
        .expect("caller has a space");
        assert_eq!(&cooked, b"a\r\nb");

        // Close the slave: the drained master read is end-of-stream, and a
        // master write breaks — fail closed, exactly like a pipe.
        assert_eq!(h.fs_close(&ctx, slave_fd), Ok(0));
        assert_eq!(h.fs_read(&ctx, master_fd, 0, 0x1100, 4), Ok(0));
        assert_eq!(
            h.fs_write(&ctx, master_fd, 0, 0x1000, 4),
            Err(Errno::BrokenPipe)
        );
    }

    /// `pty_set_size` on the **master** end updates the shared geometry both
    /// ends observe (the graphical terminal's window-resize path): the slave's
    /// `terminal_size` reports the new grid. It fails closed on a zero/oversized
    /// dimension and on a descriptor that is not a pty master of the caller
    /// (`plans/PTY.md`).
    #[test]
    fn pty_set_size_updates_the_shared_geometry_and_fails_closed() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) =
            send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, b"ping");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let caps = make_caps_record(2, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // Mint a pty at 24×80; the master end lands first at 0x1800.
        assert_eq!(h.pty_create(&ctx, 0x1800, 24, 80), Ok(0));
        let mut fds = [0u8; 8];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1800), &mut fds).expect("readable");
        })
        .expect("caller has a space");
        let master_fd = u32::from_ne_bytes([fds[0], fds[1], fds[2], fds[3]]);
        let slave_fd = u32::from_ne_bytes([fds[4], fds[5], fds[6], fds[7]]);

        // A zero (or oversized) dimension fails closed before any state moves.
        assert_eq!(
            h.pty_set_size(&ctx, master_fd, 0, 80),
            Err(Errno::OutOfRange)
        );
        assert_eq!(
            h.pty_set_size(&ctx, master_fd, 50, 0x1_0000),
            Err(Errno::OutOfRange)
        );
        // A descriptor that is not a pty master of the caller (the slave, or
        // an unopened number) fails closed with `NotFound`, never leaking
        // which case occurred.
        assert_eq!(
            h.pty_set_size(&ctx, slave_fd, 50, 100),
            Err(Errno::NotFound)
        );
        assert_eq!(h.pty_set_size(&ctx, 999, 50, 100), Err(Errno::NotFound));

        // The master-side resize updates the shared geometry: the slave's
        // `terminal_size` now reports the new grid.
        assert_eq!(h.pty_set_size(&ctx, master_fd, 50, 100), Ok(0));
        assert_eq!(h.terminal_size(&ctx, slave_fd, 0x1900, 4), Ok(4));
        let mut size = [0u8; 4];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1900), &mut size).expect("readable");
        })
        .expect("caller has a space");
        assert_eq!(
            TerminalSize::from_bytes(&size),
            Ok(TerminalSize::new(50, 100).unwrap())
        );
    }

    /// A **wired** standard descriptor (the SP10 spawn attach) routes
    /// `stream_read`/`stream_write` to its open entry with **no console
    /// capability**, and the entry's own open direction is enforced
    /// fail-closed in both directions.
    #[test]
    fn wired_streams_route_to_the_pipe_and_enforce_direction() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) =
            send_aspace(MapFlags::READ | MapFlags::WRITE | MapFlags::USER, b"data");
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        // Deliberately no CONSOLE_* capability: a pipe-backed standard
        // stream needs no console authority.
        let caps = make_caps_record(2, &[], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let h = KernelSyscallHandlers::new(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng,
        );

        // Wire the task the way a spawned child is wired: stdin = the
        // pipe's read end, stdout = its write end, console table closed.
        {
            let mut reg = aspaces.write();
            let (read_fd, write_fd) = reg.open_pipe(SecTaskId(2)).expect("pair fits");
            let read = reg
                .open_file_entry(SecTaskId(2), read_fd)
                .expect("read end");
            let write = reg
                .open_file_entry(SecTaskId(2), write_fd)
                .expect("write end");
            reg.install_std_entry(SecTaskId(2), tairix_abi::STDIN, read)
                .expect("stdin wired");
            reg.install_std_entry(SecTaskId(2), tairix_abi::STDOUT, write)
                .expect("stdout wired");
            reg.set_streams(SecTaskId(2), DescriptorTable::closed());
        }

        // stdout -> pipe -> stdin, no console anywhere.
        assert_eq!(h.stream_write(&ctx, tairix_abi::STDOUT, 0x1000, 4), Ok(4));
        assert_eq!(h.stream_read(&ctx, tairix_abi::STDIN, 0x1100, 4, 0), Ok(4));
        let mut out = [0u8; 4];
        h.with_caller_aspace(&ctx, |space, physmap| {
            copy_in(space, physmap, VirtAddr::new(0x1100), &mut out).expect("readable");
        })
        .expect("caller has a space");
        assert_eq!(&out, b"data");

        // Direction is the entry's own open flags: a read of the write end
        // and a write of the read end both fail closed.
        assert_eq!(
            h.stream_read(&ctx, tairix_abi::STDOUT, 0x1100, 4, 0),
            Err(Errno::PermissionDenied)
        );
        assert_eq!(
            h.stream_write(&ctx, tairix_abi::STDIN, 0x1000, 4),
            Err(Errno::PermissionDenied)
        );
        // A wired descriptor is not a terminal: the console-only controls
        // fail closed with `NotFound`.
        assert_eq!(
            h.stream_input_mode(&ctx, tairix_abi::STDIN, 1),
            Err(Errno::NotFound)
        );
    }

    /// The spawn attach block wires a parent pipe end into the child: the
    /// child's open table holds a counted clone of the parent's end at the
    /// standard fd, its console slot is closed, and the unwired slots
    /// inherit (`plans/SPAWN.md` SP10).
    #[test]
    fn spawn_attach_wires_a_pipe_end_into_the_child() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // The parent's pipe pair is minted first, so its descriptors are
        // deterministic (4 = read end, 5 = write end).
        let attach = SpawnAttach {
            wires: [
                FdWire::Inherit,
                FdWire::Handle(5),
                FdWire::Closed,
                FdWire::Inherit,
            ],
            ..SpawnAttach::INHERIT
        };
        let (space, physmap) = send_aspace_with_attach(SPAWN_PATH, &[attach]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let (parent_read_fd, parent_write_fd) = aspaces
            .write()
            .open_pipe(SecTaskId(2))
            .expect("pipe pair fits");
        assert_eq!((parent_read_fd, parent_write_fd), (4, 5));
        aspaces
            .write()
            .set_streams(SecTaskId(2), DescriptorTable::standard_on(1));
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
        );

        let pid = h
            .spawn(
                &ctx,
                0x1000,
                SPAWN_PATH.len(),
                attach_addr(0),
                SPAWN_ATTACH_LEN,
                0,
                0,
            )
            .expect("wired spawn succeeds");

        // The child's stdout is a counted clone of the parent's write end.
        let child_entry = aspaces
            .read()
            .open_file_entry(SecTaskId(pid), tairix_abi::STDOUT)
            .expect("wired child entry");
        let parent_entry = aspaces
            .read()
            .open_file_entry(SecTaskId(2), parent_write_fd)
            .expect("parent entry");
        assert!(child_entry
            .pipe()
            .expect("pipe end")
            .same_pipe(parent_entry.pipe().expect("pipe end")));
        assert!(child_entry.flags.is_write());
        // The wired slot's console entry is closed; the explicit `Closed`
        // wire closed stderr; the untouched slots inherit the parent's
        // console-1 table.
        let child_streams = aspaces.read().streams(SecTaskId(pid));
        assert_eq!(child_streams.mode(tairix_abi::STDOUT), StreamMode::Closed);
        assert_eq!(child_streams.mode(tairix_abi::STDERR), StreamMode::Closed);
        assert_eq!(child_streams.mode(tairix_abi::STDIN), StreamMode::Read);
        assert_eq!(child_streams.console(tairix_abi::STDIN), 1);
        // The child's end stays live independently of the parent's
        // descriptor: closing the parent's write end leaves the pipe
        // writable through the child's clone (the read end still lives).
        assert_eq!(h.fs_close(&ctx, parent_write_fd), Ok(0));
        assert_eq!(
            child_entry.pipe().expect("pipe end").try_write(b"x"),
            crate::pipe::WriteStep::Wrote(1)
        );
    }

    /// A `SPAWN_FLAG_SANDBOX` attach block admits a **parser sandbox**
    /// child: its capability record is branded sandboxed with every set
    /// forced empty — even though the program's manifest requests a
    /// capability — and its explicit all-`Closed` wires leave every
    /// standard stream denied (`docs/src/security/sandbox.md`).
    #[test]
    fn spawn_with_a_sandbox_attach_admits_an_empty_confined_child() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // A canonical sandbox block: every wire explicit (all closed
        // here), inherited credential, no console index.
        let attach = SpawnAttach::sandbox([FdWire::Closed; tairix_abi::STD_STREAM_COUNT]);
        let (space, physmap) = send_aspace_with_attach(SPAWN_PATH, &[attach]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        // The program's manifest requests a real capability; the sandbox
        // brand must strip it regardless.
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[CapabilityId::FS_MOUNT],
                    args: &[],
                },
            ])))));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
        );

        let pid = h
            .spawn(
                &ctx,
                0x1000,
                SPAWN_PATH.len(),
                attach_addr(0),
                SPAWN_ATTACH_LEN,
                0,
                0,
            )
            .expect("sandbox spawn succeeds");

        let guard = table.read();
        let record = guard.caps_for(SecTaskId(pid)).expect("child record");
        assert!(record.is_sandboxed());
        assert!(record.effective().is_empty());
        assert!(record.user_grant().is_empty());
        assert!(record.manifest_request().is_empty());
        assert!(!record.has(CapabilityId::FS_MOUNT));
        drop(guard);
        // Every standard stream is denied: the explicit `Closed` wires are
        // the whole story, nothing ambient flowed in.
        let child_streams = aspaces.read().streams(SecTaskId(pid));
        for fd in [
            tairix_abi::STDIN,
            tairix_abi::STDOUT,
            tairix_abi::STDERR,
            tairix_abi::STDINFO,
        ] {
            assert_eq!(child_streams.mode(fd), StreamMode::Closed);
        }
    }

    /// The reserved `@self` token re-spawns the **caller's own program**
    /// for a sandbox spawn: the kernel substitutes the path it admitted
    /// the caller from (its attested record, never `argv[0]`), the load
    /// gate runs as usual, and the admitted child is the same program,
    /// sandbox-branded, carrying that same attested path itself.
    #[test]
    fn spawn_self_token_respawns_the_callers_own_program_sandboxed() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let attach = SpawnAttach::sandbox([FdWire::Closed; tairix_abi::STD_STREAM_COUNT]);
        // The payload the caller passes is the token, not a path.
        let (space, physmap) = send_aspace_with_attach(tairix_abi::SPAWN_SELF, &[attach]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        // The caller's record carries the kernel-attested path it was
        // admitted from — the value the token resolves to.
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink)
            .with_spawn_path(SPAWN_PATH.to_vec());
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
        );

        let pid = h
            .spawn(
                &ctx,
                0x1000,
                tairix_abi::SPAWN_SELF.len(),
                attach_addr(0),
                SPAWN_ATTACH_LEN,
                0,
                0,
            )
            .expect("self-token sandbox spawn succeeds");

        let guard = table.read();
        let record = guard.caps_for(SecTaskId(pid)).expect("child record");
        assert!(record.is_sandboxed());
        // The child is the caller's own program: named and recorded from
        // the substituted kernel-resolved path, never the token spelling.
        assert_eq!(record.name(), ProcName::from_path(SPAWN_PATH).as_str());
        assert_eq!(record.spawn_path(), SPAWN_PATH);
    }

    /// The `@self` token serves any spawn of the caller's own binary, not
    /// only the sandbox form: a plain spawn (no attach block) re-enters
    /// the caller's own attested program as an ordinary, unsandboxed
    /// child — the load generator's worker re-entry — still resolved and
    /// admitted through the full load gate.
    #[test]
    fn spawn_self_token_serves_a_plain_spawn_of_the_callers_own_binary() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace_with_attach(tairix_abi::SPAWN_SELF, &[]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink)
            .with_spawn_path(SPAWN_PATH.to_vec());
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
        );

        let pid = h
            .spawn(&ctx, 0x1000, tairix_abi::SPAWN_SELF.len(), 0, 0, 0, 0)
            .expect("plain self-token spawn succeeds");

        let guard = table.read();
        let record = guard.caps_for(SecTaskId(pid)).expect("child record");
        // An ordinary child, not a sandbox brand: the token widens to any
        // spawn of the caller's own binary without touching the sandbox
        // posture.
        assert!(!record.is_sandboxed());
        // The child is the caller's own program: named and recorded from
        // the substituted kernel-resolved path, never the token spelling.
        assert_eq!(record.name(), ProcName::from_path(SPAWN_PATH).as_str());
        assert_eq!(record.spawn_path(), SPAWN_PATH);
    }

    /// A caller whose record carries no spawnable path (a boot principal,
    /// a kernel thread) cannot use the `@self` token even for a sandbox
    /// spawn: there is nothing attested to substitute, so the request
    /// fails closed with `NotFound`.
    #[test]
    fn spawn_self_token_refuses_a_caller_without_a_spawnable_path() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let attach = SpawnAttach::sandbox([FdWire::Closed; tairix_abi::STD_STREAM_COUNT]);
        let (space, physmap) = send_aspace_with_attach(tairix_abi::SPAWN_SELF, &[attach]);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        // No `with_spawn_path`: the record keeps the empty sentinel.
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
        );

        assert_eq!(
            h.spawn(
                &ctx,
                0x1000,
                tairix_abi::SPAWN_SELF.len(),
                attach_addr(0),
                SPAWN_ATTACH_LEN,
                0,
                0,
            ),
            Err(Errno::NotFound)
        );
    }

    /// Attach-block wiring is validated fail-closed before any child
    /// exists: a forged or foreign handle refuses the spawn with
    /// `NotFound`, and a handle whose direction cannot serve the slot is
    /// `PermissionDenied`; the producer is never reached.
    #[test]
    fn spawn_attach_refuses_forged_and_wrong_direction_handles() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        // Block 0: a handle that names no descriptor. Block 1: the pipe's
        // write end (fd 5) behind stdin, which needs a readable entry.
        let blocks = [
            SpawnAttach {
                wires: [
                    FdWire::Inherit,
                    FdWire::Handle(99),
                    FdWire::Inherit,
                    FdWire::Inherit,
                ],
                ..SpawnAttach::INHERIT
            },
            SpawnAttach {
                wires: [
                    FdWire::Handle(5),
                    FdWire::Inherit,
                    FdWire::Inherit,
                    FdWire::Inherit,
                ],
                ..SpawnAttach::INHERIT
            },
        ];
        let (space, physmap) = send_aspace_with_attach(SPAWN_PATH, &blocks);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let (_read_fd, write_fd) = aspaces
            .write()
            .open_pipe(SecTaskId(2))
            .expect("pipe pair fits");
        assert_eq!(write_fd, 5);
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
        );

        assert_eq!(
            h.spawn(
                &ctx,
                0x1000,
                SPAWN_PATH.len(),
                attach_addr(0),
                SPAWN_ATTACH_LEN,
                0,
                0,
            ),
            Err(Errno::NotFound)
        );
        assert_eq!(
            h.spawn(
                &ctx,
                0x1000,
                SPAWN_PATH.len(),
                attach_addr(1),
                SPAWN_ATTACH_LEN,
                0,
                0,
            ),
            Err(Errno::PermissionDenied)
        );
    }

    /// The attach pair's shape is validated before any state is touched: a
    /// contradictory zero-address pair, a wrong length, and a malformed
    /// block all refuse the spawn whole.
    #[test]
    fn spawn_attach_shape_violations_fail_closed() {
        install_trace_filter();
        let sink = make_sink();
        let arch = Arc::new(TestArch::with_cpus(1));
        let sched = make_sched(arch.clone());
        let table = RwLock::new(CapTable::new());
        let ipc = RwLock::new(PortRegistry::new());
        let (space, physmap) = send_aspace(MapFlags::READ | MapFlags::USER, SPAWN_PATH);
        let aspaces = RwLock::new(AddressSpaceRegistry::new());
        let rng = unseeded_rng();
        aspaces
            .write()
            .register(SecTaskId(2), space, physmap)
            .expect("caller registration");
        let irq = IrqTable::new(31);
        let ctl = UnsupportedController;
        let frames = spawn_test_frames();
        let caps = make_caps_record(2, &[CapabilityId::PROC_SPAWN], sink);
        let ctx = CallerContext {
            task_id: SecTaskId(2),
            caps: &caps,
        };
        let programs: &'static ProgramRegistry =
            Box::leak(Box::new(ProgramRegistry::new(Box::leak(Box::new([
                EmbeddedProgram {
                    path: SPAWN_PATH,
                    rxe: SPAWN_RXE,
                    caps: &[],
                    args: &[],
                },
            ])))));
        let h = spawn_handler(
            &sched, &table, &arch, sink, &irq, &ctl, &ipc, &aspaces, &rng, &frames, programs,
        );

        // Zero address with a non-zero length: a contradictory pair.
        assert_eq!(
            h.spawn(&ctx, 0x1000, SPAWN_PATH.len(), 0, SPAWN_ATTACH_LEN, 0, 0),
            Err(Errno::LengthOutOfRange)
        );
        // A present address with any length other than the fixed one.
        assert_eq!(
            h.spawn(&ctx, 0x1000, SPAWN_PATH.len(), 0x1000, 8, 0, 0),
            Err(Errno::LengthOutOfRange)
        );
        // A well-shaped pair whose bytes are not an attach block (the path
        // page) is refused by the fail-closed parser.
        assert_eq!(
            h.spawn(
                &ctx,
                0x1000,
                SPAWN_PATH.len(),
                0x1000,
                SPAWN_ATTACH_LEN,
                0,
                0,
            ),
            Err(Errno::BadMagic)
        );
    }

    /// `console_count` reports the installed list's length, and zero on
